  "覆盖报名、补件、审批和提名通知。": { en: "Covers registration, supplementary documents, approval and nomination notification.", "zh-TW": "覆蓋報名、補件、審批和提名通知。" },
  "覆盖报名资格、时间节点、材料要求和咨询方式。": { en: "Covers registration qualifications, time nodes, material requirements and consultation methods.", "zh-TW": "涵蓋報名資格、時間節點、材料要求和諮詢方式。" },
  "覆盖地理信息、海洋过程、资源环境和区域规划，强调空间分析与区域问题研究。": { en: "Covers geographical information, marine processes, resources and environment, and regional planning, emphasizing spatial analysis and regional issue research.", "zh-TW": "涵蓋地理資訊、海洋過程、資源環境和區域規劃，強調空間分析與區域問題研究。" },
  "覆盖地图、支付和就医。": { en: "Covering maps, payments and medical care.", "zh-TW": "覆蓋地圖、付款和就醫。" },
  "覆盖电路、微电子、通信与芯片器件，更偏底层硬件、信号链路与系统实现。": { en: "Covering circuits, microelectronics, communications and chip devices, focusing more on underlying hardware, signal links and system implementation.", "zh-TW": "覆蓋電路、微電子、通訊與晶片元件，更偏底層硬體、訊號鏈路與系統實作。" },
  "覆盖度": { en: "Coverage", "zh-TW": "覆蓋度" },
  "覆盖基础医学、临床培养和医工交叉，适合关注长期医学训练路径和临床实践的同学。": { en: "Covering basic medicine, clinical training and the intersection of medicine and engineering, it is suitable for students who are concerned about long-term medical training paths and clinical practice.", "zh-TW": "涵蓋基礎醫學、臨床培養和醫工交叉，適合專注於長期醫學訓練路徑和臨床實踐的同學。" },
  "覆盖交换、奖学金、竞赛等事务": { en: "Covering exchanges, scholarships, competitions and other matters", "zh-TW": "涵蓋交換、獎學金、競賽等事務" },
  "覆盖社会学、社会工作和应用心理学，强调调查方法、测量工具和现实介入能力。": { en: "Covers sociology, social work and applied psychology, emphasizing survey methods, measurement tools and real-life intervention capabilities.", "zh-TW": "涵蓋社會學、社會工作和應用心理學，強調調查方法、測量工具和現實介入能力。" },
  "覆盖校园卡、选课、住宿与就医等高频问题。": { en: "Covers high-frequency issues such as campus cards, course selection, accommodation and medical treatment.", "zh-TW": "涵蓋校園卡、選課、住宿與就醫等高頻率問題。" },
  "覆盖新闻、广电、广告与数据传播，强调采写、视听表达和内容策划能力。": { en: "Covers news, radio and television, advertising and data dissemination, emphasizing writing, audio-visual expression and content planning capabilities.", "zh-TW": "涵蓋新聞、廣電、廣告與數據傳播，強調採寫、視聽表達與內容策劃能力。" },
  "覆盖夜间出行、证件保管、财产安全和常见诈骗场景。": { en: "Covering night travel, document storage, property security and common fraud scenarios.", "zh-TW": "涵蓋夜間出行、證件保管、財產安全和常見詐騙場景。" },
