  "切换块注释": { en: "Toggle block comments", "zh-TW": "切換區塊註釋" },
  "切换为\"Ctrl+单击\"进行多光标功能": { en: "Switch to \"Ctrl+click\" for multi-cursor functionality", "zh-TW": "切換為\"Ctrl+點擊\"進行多重遊標功能" },
  "切换行注释": { en: "Toggle line comments", "zh-TW": "切換行註釋" },
